import { HttpClient } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { environment } from '../../../../environments/environment';
import { CommonModule } from '@angular/common';
import { ActivatedRoute } from '@angular/router';
import { ToastService } from '../../../common/toast.service';

@Component({
  selector: 'app-view-consultation',
  standalone: true,
  imports: [FormsModule, CommonModule],
  templateUrl: './view-consultation.component.html',
  styleUrl: './view-consultation.component.scss'
})
export class ViewConsultationComponent implements OnInit {

  consultationId: number = 0;
  safeUrl!: SafeResourceUrl;
  fileType: 'pdf' | 'other' = 'pdf';
  isLoading: boolean = true;
  isLoaded: boolean = false;
  documentLoadedOnce: boolean = false;

  stance: string = '';
  overallRemarks = '';
  partSpecificRemarks = '';
  isEcOnly = false;

  // 🔥 NEW STATES
  hasFeedback: boolean = false;
  isEditMode: boolean = false;

  constructor(
    private http: HttpClient,
    private sanitizer: DomSanitizer,
    private route: ActivatedRoute,
    private toastService: ToastService
  ) { }

  ngOnInit() {
    this.route.queryParams.subscribe(params => {
      this.consultationId = +params['id'];
      this.loadConsultation();
    });
  }

  // 🔥 LOAD CONSULTATION
  loadConsultation() {
    this.isLoading = true;
    this.isLoaded = false;

    this.http.get<any>(`${environment.apiUrl}/consultation`)
      .subscribe({
        next: (res) => {

          const data = res.data.find(
            (item: any) => item.id === this.consultationId
          );

          if (!data) {
            this.toastService.showToast('Consultation not found', 'danger');
            this.isLoading = false;
            return;
          }

          const fileUrl = `${environment.s3Url}${data.document}`;
          this.setViewer(fileUrl);

          this.isLoading = false;
          this.isLoaded = true;

          // 🔥 BEFORE calling setViewer
          this.toastService.showToast('Document is loading...', 'info');

          this.setViewer(fileUrl); this.loadFeedback();
        },

        error: (err) => {
          this.isLoading = false;
          this.toastService.showToast(err, 'danger');
        }
      });
  }

  loadFeedback() {
    this.http.get<any>(`${environment.apiUrl}/consultation/${this.consultationId}`)
      .subscribe({
        next: (res) => {

          const feedback = res?.data?.myFeedback;

          if (!feedback) {
            this.hasFeedback = false;
            return;
          }
          this.stance = feedback.stance;
          this.overallRemarks = feedback.overallRemarks;
          this.partSpecificRemarks = feedback.partSpecificRemarks;
          this.isEcOnly = feedback.isEcOnly;

          this.hasFeedback = true;
          this.isEditMode = false;
        },
        error: () => {
          this.hasFeedback = false;
        }
      });
  }

  setViewer(url: string) {
    if (!url) return;

    const ext = url.split('.').pop()?.toLowerCase();

    if (ext === 'pdf') {
      this.fileType = 'pdf';
      this.safeUrl = this.sanitizer.bypassSecurityTrustResourceUrl(url);
    } else {
      this.fileType = 'other';
      this.safeUrl = this.sanitizer.bypassSecurityTrustResourceUrl(
        `https://docs.google.com/gview?url=${encodeURIComponent(url)}&embedded=true`
      );
    }
  }

  onDocumentLoad() {
    if (this.documentLoadedOnce) return;

    this.documentLoadedOnce = true;
    this.toastService.showToast('Document loaded successfully', 'success');
  }
  // 🔥 STANCE
  setStance(value: string) {
    this.stance = value;
  }

  // 🔥 ENABLE EDIT
  enableEdit() {
    this.isEditMode = true;
  }

  // 🔥 RESET
  resetForm() {
    this.stance = '';
    this.overallRemarks = '';
    this.partSpecificRemarks = '';
    this.isEcOnly = false;
  }

  // 🔥 SUBMIT / UPDATE
  submitFeedback() {

    if (!this.stance) {
      this.toastService.showToast('Please select stance', 'danger');
      return;
    }

    const body = {
      stance: this.stance,
      overallRemarks: this.overallRemarks,
      partSpecificRemarks: this.partSpecificRemarks,
      isEcOnly: this.isEcOnly
    };

    const request = this.hasFeedback
      ? this.http.post(`${environment.apiUrl}/consultation/${this.consultationId}/feedback`, body)
      : this.http.post(`${environment.apiUrl}/consultation/${this.consultationId}/feedback`, body);

    request.subscribe({
      next: () => {
        this.toastService.showToast('Feedback saved successfully', 'success');
        this.hasFeedback = true;
        this.isEditMode = false;
      },
      error: (err) => {
        this.toastService.showToast(err, 'danger');
      }
    });
  }
}